class ExactStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.previous_spy_close = None
        self.previous_spy_sma = None

    def OnData(self, data: Slice):
        closes = {}

        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                continue

            bar = data.Bars[symbol]
            closes[ticker] = bar.Close

            if ticker in self.previous_closes:
                if bar.Close < self.previous_closes[ticker]:
                    if ticker == "AAPL":
                        self.aapl_red_streak += 1
                else:
                    if ticker == "AAPL":
                        self.aapl_red_streak = 0

            self.previous_closes[ticker] = bar.Close

        if len(closes) != len(self.symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        current_spy_close = spy_bar.Close
        current_spy_sma = self.spy_sma.Current.Value

        spy_buy_cross = (
            self.previous_spy_close is not None and
            self.previous_spy_sma is not None and
            self.previous_spy_close <= self.previous_spy_sma and
            current_spy_close > current_spy_sma
        )

        spy_sell_cross = (
            self.previous_spy_close is not None and
            self.previous_spy_sma is not None and
            self.previous_spy_close >= self.previous_spy_sma and
            current_spy_close < current_spy_sma
        )

        aapl_sell_reason = self.aapl_rsi.Current.Value > 60

        if self.strategy_a_shares > 0 and spy_sell_cross:
            self.MarketOrder(
                self.spy,
                -self.strategy_a_shares,
                tag="Strategy A liquidation"
            )
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and aapl_sell_reason:
            self.MarketOrder(
                self.aapl,
                -self.strategy_b_shares,
                tag="Strategy B liquidation"
            )
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and spy_buy_cross:
            target_value = self.Portfolio.TotalPortfolioValue * 0.40
            shares = int(target_value / current_spy_close)

            if shares > 0:
                self.MarketOrder(
                    self.spy,
                    shares,
                    tag="Strategy A buy"
                )
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 / aapl_bar.Close)

                if shares > 0:
                    self.MarketOrder(
                        self.aapl,
                        shares,
                        tag="Strategy B buy"
                    )
                    self.strategy_b_shares = shares

        self.previous_spy_close = current_spy_close
        self.previous_spy_sma = current_spy_sma
