                target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                quantity = math.floor(target_value / spy_close)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.spy_lot = quantity

            self.aapl_lot = self._get_lot_quantity(self.aapl)

            if self.aapl_lot > 0 and self.aapl_rsi.IsReady:
                if float(self.aapl_rsi.Current.Value) > 60:
                    self.MarketOrder(self.aapl, -self.aapl_lot)
                    self.aapl_lot = 0
            elif self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    quantity = math.floor(20000 / aapl_close)
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)
                        self.aapl_lot = quantity

